document.querySelectorAll('.menu-toggle').forEach(b=>{b.addEventListener('click',()=>{const n=document.getElementById(b.getAttribute('aria-controls'));const open=b.getAttribute('aria-expanded')!=='true';b.setAttribute('aria-expanded',String(open));n.classList.toggle('open',open)});});document.querySelectorAll('.links a').forEach(a=>a.addEventListener('click',()=>{document.querySelectorAll('.links').forEach(n=>n.classList.remove('open'));document.querySelectorAll('.menu-toggle').forEach(b=>b.setAttribute('aria-expanded','false'))}));document.querySelectorAll('[data-dialog]').forEach(b=>b.addEventListener('click',()=>document.getElementById(b.dataset.dialog).showModal()));document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));document.querySelectorAll('[data-demo-form]').forEach(f=>f.addEventListener('submit',e=>{e.preventDefault();f.querySelector('[role="status"]').textContent='Demonstração concluída. Nenhum dado foi enviado ou armazenado.'}));